SELECT *
FROM acc_satisfaction_collection_task
WHERE tenant_id = #{query.tenantId}
  AND project_task_id = #{query.projectTaskId}
  AND trigger_owner_context = #{query.triggerOwnerContext}
  AND trigger_object_type = #{query.triggerObjectType}
  AND trigger_fact_id = #{query.triggerFactId}
  AND trigger_fact_version = #{query.triggerFactVersion}
  AND deleted = b'0'
FOR UPDATE
